    bankName: 'Banco Popular y de Desarrollo Comunal',
    bankNameShort: 'Banco Popular',
    slug: 'banco-popular-cr',
    countrySlug: 'costarica',
    countryName: 'Costa Rica',
    flagEmoji: '🇨🇷',
    logoColor: '#00843D',
